// Generated by scripts/sync-website-demos.mjs from the website tool pages. Edit the website copy and re-run.
import type { Fact, WalkStep } from '@/app/demos/stage/types'

type Page = {
  title: string
  language: string
  images: { alt: string | null }[]
  headings: { level: number; text: string }[]
  links: { text: string }[]
}
export type Issue = { severity: 'error' | 'warning'; message: string }

function analyzeHeadings(headings: Page['headings']): Issue[] {
  const issues: Issue[] = []
  const h1Count = headings.filter((h) => h.level === 1).length
  if (h1Count === 0) issues.push({ severity: 'error', message: 'No <h1> on the page.' })
  if (h1Count > 1)
    issues.push({ severity: 'warning', message: `${h1Count} <h1> elements — ideally exactly one.` })
  for (let index = 1; index < headings.length; index += 1) {
    if (headings[index].level > headings[index - 1].level + 1) {
      issues.push({
        severity: 'warning',
        message: `Heading level jumps from h${headings[index - 1].level} to h${headings[index].level} ("${headings[index].text.slice(0, 30)}…").`,
      })
    }
  }
  for (const heading of headings) {
    if (!heading.text.trim())
      issues.push({ severity: 'warning', message: `Empty <h${heading.level}>.` })
  }
  return issues
}

function buildIssues(page: Page): Issue[] {
  const issues: Issue[] = []
  const missingAlt = page.images.filter((i) => !i.alt || !i.alt.trim()).length
  if (missingAlt > 0)
    issues.push({ severity: 'error', message: `${missingAlt} image(s) missing alt text.` })
  issues.push(...analyzeHeadings(page.headings))
  const emptyLinks = page.links.filter((l) => !l.text.trim()).length
  if (emptyLinks > 0)
    issues.push({ severity: 'warning', message: `${emptyLinks} link(s) with no accessible name.` })
  if (!page.language)
    issues.push({ severity: 'warning', message: 'Missing lang attribute on <html>.' })
  if (!page.title.trim()) issues.push({ severity: 'error', message: 'Missing page <title>.' })
  return issues
}

